INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('98ba1ffd-929d-4136-8d4c-fcc9c6b3b5ae', '2d1b78d9-c30e-40fe-b9fc-a23120520465', '2322f16e-732c-4da7-a1cf-d2df70b18e27', '2026-11-15 00:14:46.441636+00', 'recommended', 'Cereal before potatoes is the standard southern Alberta rotation: breaks Rhizoctonia and scab, residue on the sands.', 'suggested');
INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('6536f5a2-c8ed-413e-91ac-23a07d910df8', '2be09263-b21f-4d1c-b7bf-16667ab826d3', 'c3937c0c-3897-4d01-9c9b-ebed6e4cce5a', '2026-11-15 00:14:46.441636+00', 'no_go', 'Forage legume straight after forage legume: same weevils, root rots and autotoxic residue — put a cereal between.', 'suggested');
INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('b114b8a9-3ccc-4adc-aa3a-d74b473ca8c3', '2d1b78d9-c30e-40fe-b9fc-a23120520465', 'c3937c0c-3897-4d01-9c9b-ebed6e4cce5a', '2026-11-15 00:14:46.441636+00', 'recommended', 'A cereal is the standard seedbed for sainfoin.', 'suggested');
INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('ca9aa79f-0b05-4a57-a91c-8c2462700d33', 'a62e7eb6-16cc-47d1-95d2-ce4fc60c8a7a', '2be09263-b21f-4d1c-b7bf-16667ab826d3', '2026-11-15 00:14:46.441636+00', 'caution', 'Both host white mould and Fusarium/Rhizoctonia root rots, and the alfalfa gains nothing from the bean N — a cereal between is better.', 'suggested');
INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('e798057f-e5a1-4d3b-9cf1-dd6111416854', '6633db56-3ec7-4d24-9785-9fdb9ffcf9cd', '2be09263-b21f-4d1c-b7bf-16667ab826d3', '2026-11-15 00:14:46.441636+00', 'caution', 'Both host white mould and Fusarium/Rhizoctonia root rots, and the alfalfa gains nothing from the bean N — a cereal between is better.', 'suggested');
INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('4c40c175-9388-4442-813c-726189d22449', 'a68cce1b-789c-444d-913c-eb46e864bbd6', '2be09263-b21f-4d1c-b7bf-16667ab826d3', '2026-11-15 00:14:46.441636+00', 'possible', 'Canola stubble takes alfalfa well; both host sclerotinia, and volunteer canola in the new stand needs a plan.', 'suggested');
