INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('af298dc1-3e3e-407e-b70f-dfa602f08dd0', '9bd23913-c495-4bb8-a7d0-6d4db8d23e64', '2be09263-b21f-4d1c-b7bf-16667ab826d3', '2026-11-15 00:14:46.441636+00', 'possible', 'Works if the corn herbicides allow it (check the label carryover); heavy residue — seed shallow into a firm bed.', 'suggested');
